    def __init__(self, evidence=None):
        self.evidence = evidence or []
        self.calls = []
        self.exclude_urls = []
        self.embeddings = []

    def retrieve(self, claim, limit: int = 5, thresholds=None, exclude_url=None, embedding=None):
